import{_ as a,o as i,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const m=JSON.parse('{"title":"创游世界学习路线图","description":"","frontmatter":{},"headers":[],"relativePath":"教程资料/专题研究/创游世界学习路线图.md","filePath":"教程资料/专题研究/创游世界学习路线图.md","lastUpdated":1777893104000}'),d={name:"教程资料/专题研究/创游世界学习路线图.md"};function h(o,l,c,n,s,t){return i(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="创游世界学习路线图" tabindex="-1">创游世界学习路线图 <a class="header-anchor" href="#创游世界学习路线图" aria-label="Permalink to “创游世界学习路线图”">​</a></h1><p>本专题把当前知识库中已经整理出的官方教程、脚本界面、引擎更新与 B 站视频资源串成一条更适合学习与检索的路线，目标不是重复单页教程，而是回答一个更实际的问题：<strong>如果我要系统学会创游世界，应该先学什么、再学什么、每一步解决什么问题。</strong></p><h2 id="_1-学习目标拆分" tabindex="-1">1. 学习目标拆分 <a class="header-anchor" href="#_1-学习目标拆分" aria-label="Permalink to “1. 学习目标拆分”">​</a></h2><p>创游世界的学习并不是单一技能，而是至少包含以下几层：</p><ul><li>认识编辑器里的对象、素材、组件与地图</li><li>学会把素材摆进地图，并理解“素材”和“地图里的物体”不是一回事</li><li>学会给物体挂组件，让它具备功能</li><li>学会用脚本处理交互、战斗、UI、流程与数据</li><li>学会把多个系统接成完整玩法</li><li>学会根据版本更新调整旧工程做法</li></ul><p>换句话说，真正的学习路径应该是： <strong>素材认知 → 组件认知 → 脚本认知 → UI 与广播 → 系统搭建 → 版本兼容与优化。</strong></p><hr><h2 id="_2-第一阶段-先建立-编辑器世界观" tabindex="-1">2. 第一阶段：先建立“编辑器世界观” <a class="header-anchor" href="#_2-第一阶段-先建立-编辑器世界观" aria-label="Permalink to “2. 第一阶段：先建立“编辑器世界观””">​</a></h2><h3 id="这一阶段要弄懂什么" tabindex="-1">这一阶段要弄懂什么 <a class="header-anchor" href="#这一阶段要弄懂什么" aria-label="Permalink to “这一阶段要弄懂什么”">​</a></h3><ul><li>什么是素材</li><li>什么是物体</li><li>什么是组件</li><li>什么是地图层级</li><li>素材怎么移动、复制、整理到文件夹</li></ul><h3 id="为什么必须先学这个" tabindex="-1">为什么必须先学这个 <a class="header-anchor" href="#为什么必须先学这个" aria-label="Permalink to “为什么必须先学这个”">​</a></h3><p>很多新手一开始最容易混淆：</p><ul><li>为什么我改了素材，地图里的东西没变化？</li><li>为什么有的东西能加组件，有的不能？</li><li>为什么同一张贴图放到地图里以后，行为和素材库里不一样？</li></ul><p>这些问题本质上都属于“素材系统认知没建立好”。</p><h3 id="对应知识库文档" tabindex="-1">对应知识库文档 <a class="header-anchor" href="#对应知识库文档" aria-label="Permalink to “对应知识库文档”">​</a></h3><ul><li><code>docs/教程资料/官方教程知识索引.md</code></li><li><code>docs/教程资料/专题研究/素材系统与组件挂载解析.md</code></li><li><code>docs/教程资料/专题研究/素材实例化与地图物体关系解析.md</code></li><li><code>docs/OCR资料/官方教程截图转文本索引.md</code></li></ul><h3 id="学完后应该能做到" tabindex="-1">学完后应该能做到 <a class="header-anchor" href="#学完后应该能做到" aria-label="Permalink to “学完后应该能做到”">​</a></h3><ul><li>能区分素材与地图物体</li><li>知道组件是功能来源，而不是贴图本身自带</li><li>知道复制素材、移动素材、贴图文件夹这些操作属于资源管理，而不是玩法逻辑</li></ul><hr><h2 id="_3-第二阶段-建立-组件决定能力-的认知" tabindex="-1">3. 第二阶段：建立“组件决定能力”的认知 <a class="header-anchor" href="#_3-第二阶段-建立-组件决定能力-的认知" aria-label="Permalink to “3. 第二阶段：建立“组件决定能力”的认知”">​</a></h2><h3 id="这一阶段要弄懂什么-1" tabindex="-1">这一阶段要弄懂什么 <a class="header-anchor" href="#这一阶段要弄懂什么-1" aria-label="Permalink to “这一阶段要弄懂什么”">​</a></h3><ul><li>组件分类为什么这么重要</li><li>通用 / 战斗 / 装置 / 显示 / 交互 / 自定义分别解决什么问题</li><li>官方内置素材为什么往往“拿来就能用”</li><li>自制素材为什么要自己挂组件</li></ul><h3 id="核心理解" tabindex="-1">核心理解 <a class="header-anchor" href="#核心理解" aria-label="Permalink to “核心理解”">​</a></h3><p>在创游世界里，<strong>组件比贴图更接近真正的功能单元</strong>。 贴图决定“看起来像什么”，组件决定“实际上能做什么”。</p><p>例如：</p><ul><li>一个箱子贴图，如果没挂交互或物理组件，它可能只是个摆设</li><li>一个按钮贴图，如果挂了可互动、开关、广播等组件，它才真正成为机关的一部分</li></ul><h3 id="对应知识库文档-1" tabindex="-1">对应知识库文档 <a class="header-anchor" href="#对应知识库文档-1" aria-label="Permalink to “对应知识库文档”">​</a></h3><ul><li><code>docs/脚本系统/脚本界面与积木知识索引.md</code></li><li><code>docs/脚本系统/专题研究/组件添加界面深度解析.md</code></li><li><code>docs/脚本系统/专题研究/脚本组件体系与能力分层深度研究.md</code></li><li><code>docs/教程资料/专题研究/素材系统与组件挂载解析.md</code></li></ul><h3 id="学完后应该能做到-1" tabindex="-1">学完后应该能做到 <a class="header-anchor" href="#学完后应该能做到-1" aria-label="Permalink to “学完后应该能做到”">​</a></h3><ul><li>看到一个玩法需求时，先想到要挂什么组件</li><li>不再把“素材类别”和“玩法能力”混成一件事</li><li>开始形成“对象能力组合”的思维方式</li></ul><hr><h2 id="_4-第三阶段-进入脚本系统" tabindex="-1">4. 第三阶段：进入脚本系统 <a class="header-anchor" href="#_4-第三阶段-进入脚本系统" aria-label="Permalink to “4. 第三阶段：进入脚本系统”">​</a></h2><h3 id="这一阶段要弄懂什么-2" tabindex="-1">这一阶段要弄懂什么 <a class="header-anchor" href="#这一阶段要弄懂什么-2" aria-label="Permalink to “这一阶段要弄懂什么”">​</a></h3><ul><li>自定义组件是什么</li><li>属性、指令、触发时机分别扮演什么角色</li><li>局部变量 / 自身属性 / 地图属性 / 系统属性的区别</li><li>常见积木块能控制什么</li></ul><h3 id="核心理解-1" tabindex="-1">核心理解 <a class="header-anchor" href="#核心理解-1" aria-label="Permalink to “核心理解”">​</a></h3><p>脚本系统不是孤立存在的，它通常挂在组件和对象上执行。 因此更准确地说，创游世界的脚本学习不是“学代码”，而是“学对象、组件、事件和数据如何组合起来”。</p><h3 id="建议先掌握的最小闭环" tabindex="-1">建议先掌握的最小闭环 <a class="header-anchor" href="#建议先掌握的最小闭环" aria-label="Permalink to “建议先掌握的最小闭环”">​</a></h3><ol><li>给对象加一个自定义组件</li><li>定义一个属性存状态</li><li>定义一个指令作为外部调用入口</li><li>在触发时机里修改属性</li><li>用广播或其他对象调用该指令</li></ol><p>只要这个闭环能通，你就已经跨过“看教程”和“会做功能”之间最大的门槛。</p><h3 id="对应知识库文档-2" tabindex="-1">对应知识库文档 <a class="header-anchor" href="#对应知识库文档-2" aria-label="Permalink to “对应知识库文档”">​</a></h3><ul><li><code>docs/脚本系统/专题研究/自定义组件深度解析.md</code></li><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li><code>docs/脚本系统/专题研究/系统级脚本能力解析.md</code></li><li><code>docs/OCR资料/基础写脚本界面截图转文本.md</code></li></ul><h3 id="学完后应该能做到-2" tabindex="-1">学完后应该能做到 <a class="header-anchor" href="#学完后应该能做到-2" aria-label="Permalink to “学完后应该能做到”">​</a></h3><ul><li>理解脚本的执行入口不是只有一个</li><li>能分清临时变量、对象状态、地图状态、系统状态</li><li>能写简单的交互逻辑、流程逻辑和对象行为逻辑</li></ul><hr><h2 id="_5-第四阶段-学会用广播和-ui-解耦" tabindex="-1">5. 第四阶段：学会用广播和 UI 解耦 <a class="header-anchor" href="#_5-第四阶段-学会用广播和-ui-解耦" aria-label="Permalink to “5. 第四阶段：学会用广播和 UI 解耦”">​</a></h2><h3 id="这一阶段要弄懂什么-3" tabindex="-1">这一阶段要弄懂什么 <a class="header-anchor" href="#这一阶段要弄懂什么-3" aria-label="Permalink to “这一阶段要弄懂什么”">​</a></h3><ul><li>广播为什么重要</li><li>为什么地图逻辑和 UI 逻辑不应该乱写在一起</li><li>地图 UI、操作 UI、物体 UI 分别适合干什么</li><li>联机环境下 UI 为什么要注意“当前 UI”的访问方式</li></ul><h3 id="核心理解-2" tabindex="-1">核心理解 <a class="header-anchor" href="#核心理解-2" aria-label="Permalink to “核心理解”">​</a></h3><p>广播的真正价值，不是“能发消息”，而是： <strong>让不同对象、不同层级、不同系统之间尽量不要硬绑死。</strong></p><p>而 UI 的真正难点也不是“显示东西”，而是： <strong>如何把地图状态、玩家状态、系统状态正确地同步到界面。</strong></p><h3 id="对应知识库文档-3" tabindex="-1">对应知识库文档 <a class="header-anchor" href="#对应知识库文档-3" aria-label="Permalink to “对应知识库文档”">​</a></h3><ul><li><code>docs/教程资料/专题研究/广播机制深度解析.md</code></li><li><code>docs/教程资料/专题研究/UI系统与切换机制解析.md</code></li><li><code>docs/引擎更新/专题研究/联机UI演进专题.md</code></li></ul><h3 id="学完后应该能做到-3" tabindex="-1">学完后应该能做到 <a class="header-anchor" href="#学完后应该能做到-3" aria-label="Permalink to “学完后应该能做到”">​</a></h3><ul><li>用广播触发 UI 更新，而不是到处直接改界面</li><li>知道什么信息该放地图层，什么信息该放 UI 层</li><li>能看懂旧教程和新版本在 UI 调用方式上的差别</li></ul><hr><h2 id="_6-第五阶段-开始搭-完整玩法系统" tabindex="-1">6. 第五阶段：开始搭“完整玩法系统” <a class="header-anchor" href="#_6-第五阶段-开始搭-完整玩法系统" aria-label="Permalink to “6. 第五阶段：开始搭“完整玩法系统””">​</a></h2><h3 id="这一阶段要做什么" tabindex="-1">这一阶段要做什么 <a class="header-anchor" href="#这一阶段要做什么" aria-label="Permalink to “这一阶段要做什么”">​</a></h3><p>把前面学到的素材、组件、脚本、UI、广播真正组合起来，做完整系统。</p><h3 id="最适合练手的系统" tabindex="-1">最适合练手的系统 <a class="header-anchor" href="#最适合练手的系统" aria-label="Permalink to “最适合练手的系统”">​</a></h3><ul><li>血条 / 生命系统</li><li>货币 / 货币条系统</li><li>拾取与背包雏形</li><li>武器伤害系统</li><li>按钮 / 开关 / 门机关联动</li><li>签到 / 抽奖 / 奖励领取</li></ul><h3 id="这些系统为什么适合练手" tabindex="-1">这些系统为什么适合练手 <a class="header-anchor" href="#这些系统为什么适合练手" aria-label="Permalink to “这些系统为什么适合练手”">​</a></h3><p>因为它们往往会同时覆盖：</p><ul><li>对象状态</li><li>UI 展示</li><li>事件触发</li><li>数据读写</li><li>多对象协作</li></ul><p>也就是说，一个功能做通了，通常就不是只学会一个按钮，而是学会一整套系统思维。</p><h3 id="对应知识库来源" tabindex="-1">对应知识库来源 <a class="header-anchor" href="#对应知识库来源" aria-label="Permalink to “对应知识库来源”">​</a></h3><ul><li>官方教程 OCR 中的生命、货币、武器、拾取参数等页面</li><li>脚本界面 OCR 中的系统级脚本与动作块</li><li>B 站资源清单中的血条、翻滚、背包、抽奖、签到等视频主题</li></ul><hr><h2 id="_7-第六阶段-学会看版本更新-避免学成过时做法" tabindex="-1">7. 第六阶段：学会看版本更新，避免学成过时做法 <a class="header-anchor" href="#_7-第六阶段-学会看版本更新-避免学成过时做法" aria-label="Permalink to “7. 第六阶段：学会看版本更新，避免学成过时做法”">​</a></h2><h3 id="为什么必须学这个" tabindex="-1">为什么必须学这个 <a class="header-anchor" href="#为什么必须学这个" aria-label="Permalink to “为什么必须学这个”">​</a></h3><p>创游世界并不是静止的，UI、数据类型、脚本能力、联机逻辑、声音系统、调试方式都在持续更新。 如果只看旧视频，容易学到：</p><ul><li>已不推荐的 UI 写法</li><li>老的兼容逻辑</li><li>旧版本 Bug 绕法</li><li>已被新版本替代的工作流</li></ul><h3 id="应重点关注的版本主题" tabindex="-1">应重点关注的版本主题 <a class="header-anchor" href="#应重点关注的版本主题" aria-label="Permalink to “应重点关注的版本主题”">​</a></h3><ul><li><code>4.54.0</code>：结构体、单选值、数学能力、联机 UI 调整</li><li><code>4.52.x</code>：当前 UI、上传并等待、联机 UI 本地化</li><li><code>4.43.24</code>：BGM / UI 类型、当前 UI 元素属性</li><li><code>4.40.17</code>：逐行 Debug 与调用栈</li><li><code>4.40.5</code>：多人同时编辑工程</li></ul><h3 id="对应知识库文档-4" tabindex="-1">对应知识库文档 <a class="header-anchor" href="#对应知识库文档-4" aria-label="Permalink to “对应知识库文档”">​</a></h3><ul><li><code>docs/引擎更新/引擎更新知识索引.md</code></li><li><code>docs/引擎更新/专题研究/4.54.0 数据类型与脚本能力升级解析.md</code></li><li><code>docs/引擎更新/专题研究/联机UI演进专题.md</code></li><li><code>docs/OCR资料/引擎更新截图转文本.md</code></li></ul><h3 id="学完后应该能做到-4" tabindex="-1">学完后应该能做到 <a class="header-anchor" href="#学完后应该能做到-4" aria-label="Permalink to “学完后应该能做到”">​</a></h3><ul><li>知道某个教程是不是老版本做法</li><li>能根据版本变化调整工程架构</li><li>能更理性地判断“这是引擎限制，还是教程过时”</li></ul><hr><h2 id="_8-推荐的实际学习顺序" tabindex="-1">8. 推荐的实际学习顺序 <a class="header-anchor" href="#_8-推荐的实际学习顺序" aria-label="Permalink to “8. 推荐的实际学习顺序”">​</a></h2><p>如果按最省力的路线，建议顺序如下：</p><ol><li>先看“什么是素材 / 什么是组件 / 地图层级”</li><li>再看“组件分类和组件挂载”</li><li>再学“自定义组件、属性、指令、触发时机”</li><li>再学“作用域和数据流”</li><li>再学“广播和 UI”</li><li>再做“生命 / 货币 / 拾取 / 门机关”这些小系统</li><li>最后把引擎更新补进自己的认知模型里</li></ol><p>这是因为：</p><ul><li>没搞懂素材和组件，脚本会学得很虚</li><li>没搞懂作用域，脚本很容易写乱</li><li>没搞懂广播和 UI，系统一复杂就会缠死</li><li>不看版本更新，越学越容易踩旧坑</li></ul><hr><h2 id="_9-当前知识库最适合支持哪类学习者" tabindex="-1">9. 当前知识库最适合支持哪类学习者 <a class="header-anchor" href="#_9-当前知识库最适合支持哪类学习者" aria-label="Permalink to “9. 当前知识库最适合支持哪类学习者”">​</a></h2><h3 id="新手" tabindex="-1">新手 <a class="header-anchor" href="#新手" aria-label="Permalink to “新手”">​</a></h3><p>最适合从：</p><ul><li><code>官方教程知识索引</code></li><li><code>素材系统与组件挂载解析</code></li><li><code>创游世界学习路线图</code> 开始</li></ul><h3 id="已会摆素材、但不会写系统的人" tabindex="-1">已会摆素材、但不会写系统的人 <a class="header-anchor" href="#已会摆素材、但不会写系统的人" aria-label="Permalink to “已会摆素材、但不会写系统的人”">​</a></h3><p>最适合从：</p><ul><li><code>自定义组件深度解析</code></li><li><code>脚本作用域与数据流深度研究</code></li><li><code>广播机制深度解析</code> 开始</li></ul><h3 id="已会做基础玩法、想进阶的人" tabindex="-1">已会做基础玩法、想进阶的人 <a class="header-anchor" href="#已会做基础玩法、想进阶的人" aria-label="Permalink to “已会做基础玩法、想进阶的人”">​</a></h3><p>最适合从：</p><ul><li><code>联机UI演进专题</code></li><li><code>4.54.0 数据类型与脚本能力升级解析</code></li><li><code>B站创游世界视频资源清单</code> 开始</li></ul><hr><h2 id="_10-这份路线图在知识库里的作用" tabindex="-1">10. 这份路线图在知识库里的作用 <a class="header-anchor" href="#_10-这份路线图在知识库里的作用" aria-label="Permalink to “10. 这份路线图在知识库里的作用”">​</a></h2><p>这份文档不直接替代原始教程，也不替代 OCR 证据页。它更像是知识库的“导航层”，专门负责：</p><ul><li>帮新手决定先学什么</li><li>帮进阶用户决定该补什么短板</li><li>帮 AI 在回答“我该怎么学创游世界”时有一条清晰路径</li><li>把官方教程、脚本界面、引擎更新、视频资源四类资料串成一个整体</li></ul><hr><h2 id="_11-可检索关键词" tabindex="-1">11. 可检索关键词 <a class="header-anchor" href="#_11-可检索关键词" aria-label="Permalink to “11. 可检索关键词”">​</a></h2><ul><li>创游世界学习路线</li><li>创游世界怎么学</li><li>新手先学什么</li><li>素材和组件区别</li><li>自定义组件入门</li><li>脚本作用域</li><li>广播和 UI</li><li>联机 UI 学习顺序</li><li>创游世界进阶路线</li><li>创游世界知识地图</li></ul>',101)])])}const u=a(d,[["render",h]]);export{m as __pageData,u as default};
